#include <stdio.h>

void print_hand(int count) {
    if (count == 0) {
        printf("*\n");
    } else {
        for (int i = 0; i < count; i++) {
            putchar('I');
        }
        putchar('\n');
    }
}

int main(void) {
    int n;
    if (scanf("%d", &n) == 1) {
        if (n <= 5) {
            print_hand(n);
            print_hand(0);
        } else {
            print_hand(5);
            print_hand(n - 5);
        }
    }
    return 0;
}
